const body = $input.first().json.body || $input.first().json;
const valorBruto = body.valor_lance_vencedor;
const valor = valorBruto != null && valorBruto !== '' ? Number(valorBruto) : null;
return [{ json: {
  resumo_id: body.resumo_id || null,
  usuario_id: body.usuario_id || null,
  valor_lance_vencedor: (valor != null && !isNaN(valor) && valor > 0) ? valor : null
} }];

const empresa = $input.first().json || {};
const resumo = $('Buscar Resumo Readequar').first().json;
const usuario = $('Buscar Usuario Readequar').first().json;
const ctx = $('Extrair Corpo Readequar').first().json;
return [{ json: {
  resumo_id: resumo.id,
  usuario_id: usuario.usuario_id,
  valor_lance_vencedor: ctx.valor_lance_vencedor,
  razao_social: empresa.razao_social || '[RAZAO SOCIAL A PREENCHER]',
  cnpj: empresa.cnpj || '[CNPJ A PREENCHER]',
  endereco: empresa.endereco || '[ENDERECO A PREENCHER]',
  responsavel_legal: empresa.responsavel_legal || '[RESPONSAVEL LEGAL A PREENCHER]',
  objeto_resumo: resumo.objeto_resumo,
  tipo_disputa: resumo.tipo_disputa,
  prazo_entrega: resumo.prazo_entrega,
  documentos_exigidos: resumo.documentos_exigidos,
  whatsapp_numero: usuario.whatsapp_numero
} }];

const aiOutput = $input.first().json;
const texto = (aiOutput.message && aiOutput.message.content) || '';
const ctx = $('Montar Contexto Readequacao').first().json;
return [{ json: { ...ctx, conteudo_proposta: texto } }];

