const ctx = $('Extrair Texto Readequacao').first().json;
const texto = '📝 PROPOSTA READEQUADA -- revise antes de enviar. Valor ajustado pro lance vencedor informado: R$ ' +
  ctx.valor_lance_vencedor.toLocaleString('pt-BR', { minimumFractionDigits: 2 }) + '.\n\n' + ctx.conteudo_proposta;
return [{ json: { numero: (ctx.whatsapp_numero || '').replace(/\D/g, ''), texto } }];

const ctx = $('Extrair Corpo Readequar').first().json;
const resumo = $('Buscar Resumo Readequar').first().json;
const usuario = $('Buscar Usuario Readequar').first().json || {};
if (!usuario.whatsapp_numero) return [];
let texto;
if (!ctx.valor_lance_vencedor) {
  texto = 'Pra readequar a proposta preciso que voce me diga o valor exato do lance vencedor (ex: "o lance vencedor foi R$ 78.500"). Nao decido esse valor sozinho.';
} else {
  const explicacoes = {
    identificada: 'essa licitacao ainda nao foi analisada',
    analisada: 'essa licitacao ainda nao tem proposta enviada -- so da pra readequar depois que a proposta original ja foi gerada',
    vencida: 'essa licitacao ja foi marcada como vencida',
    perdida: 'essa licitacao ja foi marcada como perdida',
    proposta_readequada: 'essa licitacao ja esta readequada -- confirme o resultado antes de readequar de novo',
    contrato_gerado: 'essa licitacao ja tem contrato gerado'
  };
  const motivo = explicacoes[resumo.fase_atual] || ('a licitacao esta na fase "' + resumo.fase_atual + '"');
  texto = 'Nao consigo readequar a proposta agora: ' + motivo + '.';
}
return [{ json: { numero: usuario.whatsapp_numero.replace(/\D/g, ''), texto } }];
